-- study_type
update public.fields set verification_status='verified_against_standard', verification_quote='Una evaluación de la huella de agua de acuerdo con esta Norma Internacional debe incluir las cuatro fases del análisis del ciclo de vida: a) definición del objetivo y alcance (véase 5.2); b) análisis del inventario de la huella de agua (véase 5.3); c) evaluación del impacto de la huella de agua (véase 5.4); y d) interpretación de los resultados (véase 5.5). | Un estudio del inventario de la huella de agua de acuerdo con esta Norma Internacional debe incluir las siguientes tres fases del análisis del ciclo de vida: - definición del objetivo y del alcance (véase 5.2); - análisis del inventario de la huella de agua (véase 5.3); e -interpretación de los resultados (véase 5.5). — printed p.10', verification_note='md-verified 2026-09-05 (§5.1, printed p.10 derived from CONTENIDO) [VC] — the two enum tokens are exactly the two study kinds §5.1 distinguishes (four-phase assessment vs three-phase inventory study). §5.1 adds a rule the encoding does NOT carry as a field or gate: "Se puede realizar el informe de los resultados del análisis del inventario de la huella de agua, pero no debe realizar el informe como huella de agua." (STAGED S-9)', verified_at=now() where id='82351643-deac-4aaf-8813-874148abedf6' and verification_status not in ('verified_against_standard','corrected');
