update public.fields set verification_status='verified_against_standard', verification_quote='La evaluación de la huella de agua se puede realizar como una evaluación única e independiente, o como parte del análisis del ciclo de vida. | Esta Norma Internacional proporciona los principios, los requisitos y las directrices para realizar e informar de una evaluación de huella de agua única o individual, o como parte de una evaluación ambiental más integral. — printed p.10, p.1', verification_note='md-verified 2026-09-05 (§5.1 + §1, printed p.10 / p.1 derived from CONTENIDO) [VC] — the two enum tokens (standalone / part_of_lca) are the two modes named in both clauses', verified_at=now() where id='8f3c9da4-519d-41f5-82b0-8a9c6da9a173' and verification_status not in ('verified_against_standard','corrected');
