-- life_cycle_perspective
update public.fields set verification_status='verified_against_standard', verification_quote='La evaluación de la huella de agua de un producto considera todas las etapas del ciclo de vida del producto, según sea apropiado, desde la materia prima hasta su disposición final. [...] Una evaluación de la huella de agua de una organización adopta una perspectiva del ciclo de vida basada en todas sus actividades. Si es apropiado, y se justifica, la evaluación de la huella de agua puede restringirse a una o a varias etapas del ciclo de vida. — printed p.8', verification_note='md-verified 2026-09-05 (§4.2, printed p.8 derived from CONTENIDO) [VC] — CAVEAT: §4.2 carries NO modal verb ("considera", not "debe considerar") and expressly permits restriction to selected life-cycle stages, so the encoded is_required=true plus the block gate REQ-02 over-enforce a descriptive principle (STAGED S-2, S-6)', verified_at=now() where id='35de4319-19e2-4376-9e99-38e2aac7db5b' and verification_status not in ('verified_against_standard','corrected');
-- comprehensive_assessment
update public.fields set verification_status='verified_against_standard', verification_quote='La huella de agua es el resultado de una evaluación integral, con la cual se obtiene un perfil de resultados del indicador de categoría de impacto. | Cuando se realiza una evaluación integral, se debe demostrar que todos los impactos ambientales significativos potenciales relacionados con el agua se hayan tratado por las categorías de impacto seleccionadas La falta de datos no puede ser una justificación para no tomar en cuenta una categoría de impacto importante. — printed p.10', verification_note='md-verified 2026-09-05 (§5.1, printed p.10 derived from CONTENIDO) [VC] — the missing full stop after "seleccionadas" is the transcript as printed; §4.13 gives the matching principle ("Una huella de agua considera todos los atributos ambientales pertinentes ...", p.9)', verified_at=now() where id='0584055d-071f-4dad-a956-046b961b0922' and verification_status not in ('verified_against_standard','corrected');
-- water_footprint_qualifier
update public.fields set verification_status='verified_against_standard', verification_quote='Los resultados de una evaluación de la huella de agua no integral se deben expresar en el informe, como huella de agua con un calificativo; por ejemplo: "huella de agua según disponibilidad"; "huella de agua según la escasez", "huella de agua según la eutrofización"; "huella de agua según la ecotoxicidad"; "huella de agua según la acidificación", "huella de agua no integral". | El término "huella de agua" de una organización, sin el calificativo, se debe utilizar solamente si se consideraron los inventarios directos e indirectos de la organización en una evaluación de la huella de agua integral. — printed p.10', verification_note='md-verified 2026-09-05 (§5.1, printed p.10 derived from CONTENIDO) [VC] — the encoded data_type=text is right: §5.1 and §6.1 give the qualifiers as "por ejemplo" lists, not a closed set, so this is NOT a fixed-options selection case. NOTE the second sentence is organization-specific ("de una organización" / "de la organización"); gate REQ-13 quotes it with those words removed (STAGED S-5)', verified_at=now() where id='d83fbda1-6168-4de6-a5de-2e5fd3cf3fbc' and verification_status not in ('verified_against_standard','corrected');
-- pcr_adopted
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando existan reglas de categoría de producto pertinentes, éstas deberían de adoptarse, siempre que: - hayan sido desarrolladas de conformidad con la Norma ISO 14025, y - sean consideradas apropiadas (por ejemplo: límites del sistema, modularidad, asignación o calidad e los datos) por la organización que aplique esta Norma Internacional. — printed p.10', verification_note='md-verified 2026-09-05 (§5.1, printed p.10 derived from CONTENIDO) [VC] — "deberían de adoptarse" = should, so is_required=false is correct. "calidad e los datos" is the transcript as printed (for "calidad de los datos")', verified_at=now() where id='41903319-92ed-4b95-bf44-ef70d4751e01' and verification_status not in ('verified_against_standard','corrected');
-- consolidation_method
update public.fields set verification_status='verified_against_standard', verification_quote='La organización debe consolidar los impactos ambientales potenciales de sus instalaciones relacionadas con el agua mediante uno de los siguientes enfoques: a) control: la organización realiza la evaluación de los impactos ambientales potenciales relacionados con el agua, de los procesos y de las unidades físicas de instalaciones sobre las qué tiene el control financiero; b) participación de capital: la organización realiza la evaluación de los impactos ambientales potenciales relacionados con el agua de los procesos y de las unidades físicas de sus respectivas instalaciones de acuerdo a sus intereses de participación de capital. | La organización debe documentar qué método de consolidación aplica. — printed p.35–37', verification_note='md-verified 2026-09-05 (Anexo A.2, normativo; printed p.35–37 = the Anexo A span, derived from CONTENIDO — the md heading lost its "A." prefix and reads "2. LOS LÍMITES DE LA ORGANIZACIÓN") [VC] — the two enum tokens are exactly the two printed approaches; the choice is a genuine engineer selection (SR-2), not a default', verified_at=now() where id='5225c7ca-b10e-4257-b750-d9a781caefc0' and verification_status not in ('verified_against_standard','corrected');

