update public.fields set verification_status='verified_against_standard', verification_quote='Los límites del sistema determinan qué procesos unitarios deben incluirse dentro de la evaluación de la huella de agua. La selección de los límites del sistema debe ser coherente con el objetivo del estudio. Los criterios utilizados para establecer los límites del sistema se deben identificar y explicar. | Los límites del sistema para la evaluación de la huella de agua se deben documentar de manera clara y deben de indicar si es que la huella de agua se determinará para un producto específico, proceso u organización. Si la huella de agua se va a determinar para un producto, se deben aplicar los requisitos y directrices de la Norma ISO 14044 sobre los límites del sistema. — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.3, third-level clause with no CONTENIDO entry -> cited as the §5.2 span p.11–15) [VC] — the ISO 14044 hand-off makes the product-boundary detail NR (ISO 14044 not in the library)', verified_at=now() where id='65480b53-0443-4e7f-9963-87b2a83af8f6' and verification_status not in ('verified_against_standard','corrected');
