update public.fields set verification_status='verified_against_standard', verification_quote='Al definir el alcance del estudio, los siguientes elementos se deben de considerar y describir claramente, tomando en cuenta los requisitos y la orientación dada en los capítulos pertinentes: [...] e) criterios de corte; | Criterios de corte. Especificación de la cantidad de flujo de materia o de energía o del nivel de importancia ambiental asociado a los procesos unitarios o al sistema del producto para su exclusión del estudio. — printed p.11–15, p.3', verification_note='md-verified 2026-09-05 (§5.2.2 e + definition §3.3.9, FUENTE ISO 14040:2006 3.18; §5.2.2 cited as the §5.2 span p.11–15, §3.3 starts p.3 per CONTENIDO) [VC]', verified_at=now() where id='2597d1f5-d0fc-43a7-8fd2-a531771f20bf' and verification_status not in ('verified_against_standard','corrected');
-- allocation_procedure
update public.fields set verification_status='verified_against_standard', verification_quote='a) Paso 1: Siempre que sea posible, se debería evitar la asignación al: - dividir el proceso unitario a asignar, en dos o más sub-procesos y recopilar los datos de entrada y salida relacionados con estos sub-procesos, o - ampliar el sistema del producto para incluir las funciones adicionales relacionadas con los coproductos tomando en cuenta los requisitos del límite del sistema. b) Paso 2: Cuando no se pueda evitar la asignación, las entradas y salidas del sistema deberían dividirse entre sus diferentes productos o funciones, de tal forma que reflejen las relaciones físicas subyacentes entre ellos [...] c) Paso 3: cuando la relación física por sí misma no se pueda establecer o utilizar como base de la asignación, las entradas y salidas deberían asignarse entre los productos y las funciones de tal forma que reflejen otras relaciones entre ellos. Por ejemplo: los datos de entrada y salida podrían asignarse entre coproductos en proporción al valor económico de los productos. — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.3.2, third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — the four enum tokens map 1:1 onto the printed stepwise procedure (Paso 1 subdivision / Paso 1 system expansion / Paso 2 physical relationship / Paso 3 other e.g. economic value). The steps are "debería" (should) while §5.3.3.1 "Los procedimientos de asignación deben estar claramente definidos" is shall, so is_required=true is anchored on the shall. Field sits on ws 02 but its gate REQ-11 sits on ws 03 (STAGED S-7)', verified_at=now() where id='219877f5-3b4b-4024-895f-366dbd108143' and verification_status not in ('verified_against_standard','corrected');
-- lcia_methodology
update public.fields set verification_status='verified_against_standard', verification_quote='Al definir el alcance del estudio, los siguientes elementos se deben de considerar y describir claramente, tomando en cuenta los requisitos y la orientación dada en los capítulos pertinentes: [...] h) metodología de evaluación del impacto de la huella de agua, y las categorías de impacto seleccionadas (véase 5.4); — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.2 h; §5.2.2 cited as the §5.2 span p.11–15) [VC] — is_required=true but NO gate on any worksheet reads this field (STAGED S-10)', verified_at=now() where id='7f7223a5-d933-463b-913d-4221ee5bf7b9' and verification_status not in ('verified_against_standard','corrected');
-- results_type
update public.fields set verification_status='verified_against_standard', verification_quote='Al definir el alcance del estudio, los siguientes elementos se deben de considerar y describir claramente, tomando en cuenta los requisitos y la orientación dada en los capítulos pertinentes: [...] i) considerar si los resultados de la evaluación de la huella de agua van a incluir un resultado del indicador del impacto (y especificar cuál), un perfil de la huella de agua, y/o una huella de agua después de la ponderación (véase 5.4.1); — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.2 i; §5.2.2 cited as the §5.2 span p.11–15) [VC] — the three enum tokens are exactly the three printed result kinds. CAVEAT: the printed "y/o" makes this multi-select, but the field is a single-value enum (STAGED S-12). is_required=true with no gate reading it (STAGED S-10)', verified_at=now() where id='1b4d1d5a-c3dd-41c1-bd17-68284387ac27' and verification_status not in ('verified_against_standard','corrected');
-- baseline_conditions
update public.fields set verification_status='verified_against_standard', verification_quote='Al definir el alcance del estudio, los siguientes elementos se deben de considerar y describir claramente [...]: n) condiciones de la línea base con las que se comparen las condiciones actuales causadas por las actividades, si es aplicable; NOTA Las condiciones de la línea base pueden incluir el período utilizado como referencia para la comparación y su inventario. | Se deben considerar los valores absolutos así como las diferencias de la línea base para las cantidades de consumo de agua y las emisiones/vertidos, donde aplique y sea pertinente. — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.2 n + NOTA and §5.2.4.1; both third-level, cited as the §5.2 span p.11–15) [VC] — "si es aplicable" matches is_required=false', verified_at=now() where id='16dcc3a1-17c6-464a-8b41-37bdcd391478' and verification_status not in ('verified_against_standard','corrected');
-- report_type
update public.fields set verification_status='verified_against_standard', verification_quote='Al definir el alcance del estudio, los siguientes elementos se deben de considerar y describir claramente [...]: o) tipo de informe (véase el Capítulo 6); | El tipo y formato del informe debe determinarse en la fase de definición del objetivo y alcance del estudio. — printed p.11–15, p.28', verification_note='md-verified 2026-09-05 (§5.2.2 o + §6.1; §5.2.2 cited as the §5.2 span p.11–15, §6.1 p.28 per CONTENIDO) [VC] — CAVEAT: the two enum tokens internal / third_party are the EKOWAI granularity; §6 names only the third-party report ("informe de tercera parte", §6.2) and never prints a closed list of report types', verified_at=now() where id='f3342599-2003-4c6e-abf1-a3bea77cf1ca' and verification_status not in ('verified_against_standard','corrected');
-- critical_review_type
update public.fields set verification_status='verified_against_standard', verification_quote='Al definir el alcance del estudio, los siguientes elementos se deben de considerar y describir claramente [...]: p) tipo de revisión crítica. Si hay (véase el Capítulo 7). | El alcance y tipo de la revisión crítica deseada debe definirse en la fase del alcance de la evaluación de la huella de agua, y la decisión sobre el tipo de revisión crítica debe registrarse. — printed p.11–15, p.33', verification_note='md-verified 2026-09-05 (§5.2.2 p + §7.1; §5.2.2 cited as the §5.2 span p.11–15, §7.1 p.33 per CONTENIDO) [VC] — "p) tipo de revisión crítica. Si hay" is the transcript as printed. The three enum tokens map onto §7.1 (none), §7.3 (internal/external expert) and §7.4 (panel of interested parties). is_required=true with no gate reading it (STAGED S-10)', verified_at=now() where id='b8f66ce9-69c9-489a-aada-60042cab4295' and verification_status not in ('verified_against_standard','corrected');
-- water_quantities
update public.fields set verification_status='verified_against_standard', verification_quote='Entre otros datos por recopilar, los siguientes datos relacionados con el agua se deben considerar para su recopilación: a) cantidades de agua utilizada (incluyendo la liberación y extracción del agua) (véase 5.3.2); | Cuando se hayan considerado cualquiera de estos elementos, pero no se hayan incluido, se debe documentar la base para la exclusión. — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.4.1 a; third-level clause with no CONTENIDO entry -> cited as the §5.2 span p.11–15) [VC] — the duty is "se deben considerar para su recopilación" (shall be CONSIDERED), with an explicit escape: an element may be excluded if the basis is documented. The block gate REQ-05 demands a value with no exclusion path and no field to record the exclusion basis (STAGED S-3)', verified_at=now() where id='48070532-7007-4af8-9b91-220467ecbb1c' and verification_status not in ('verified_against_standard','corrected');
-- water_resource_types
update public.fields set verification_status='verified_against_standard', verification_quote='Entre otros datos por recopilar, los siguientes datos relacionados con el agua se deben considerar para su recopilación: [...] b) tipos de recursos de agua utilizados (incluidos para la extracción del agua y para el cuerpo receptor del agua) (véase 5.3.2); — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.4.1 b; third-level clause with no CONTENIDO entry -> cited as the §5.2 span p.11–15) [VC] — planning-level restatement of the per-flow field flow_water_resource_type on ws 03 (same "véase 5.3.2" pointer); layer duplication, see STAGED S-11', verified_at=now() where id='36800877-e51a-4b9c-8235-74c609a6722f' and verification_status not in ('verified_against_standard','corrected');
-- water_quality_data
update public.fields set verification_status='verified_against_standard', verification_quote='Entre otros datos por recopilar, los siguientes datos relacionados con el agua se deben considerar para su recopilación: [...] c) los datos que describen la calidad del agua (incluidos para la extracción del agua, la liberación y para el cuerpo receptor de agua) (véase 5.3.2); — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.4.1 c; third-level clause with no CONTENIDO entry -> cited as the §5.2 span p.11–15) [VC] — planning-level restatement of flow_quality_parameters on ws 03 (STAGED S-11)', verified_at=now() where id='8de39fb8-7566-4636-8edb-ced4588da840' and verification_status not in ('verified_against_standard','corrected');
-- forms_of_water_use
update public.fields set verification_status='verified_against_standard', verification_quote='Entre otros datos por recopilar, los siguientes datos relacionados con el agua se deben considerar para su recopilación: [...] d) formas de uso del agua (véase 5.3.2); — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.4.1 d; third-level clause with no CONTENIDO entry -> cited as the §5.2 span p.11–15) [VC] — planning-level restatement of flow_form_of_use on ws 03 (STAGED S-11)', verified_at=now() where id='8eed86c4-b3ac-4ddc-b7c5-8800bc2e81a9' and verification_status not in ('verified_against_standard','corrected');
-- water_use_locations
update public.fields set verification_status='verified_against_standard', verification_quote='Entre otros datos por recopilar, los siguientes datos relacionados con el agua se deben considerar para su recopilación: [...] f) los lugares del uso del agua (incluidos para la extracción del agua, liberación del agua o la influencia en la calidad del agua) que se requieren para determinar algún indicador de condición ambiental relacionado con el área donde tiene lugar el uso del agua (véase 5.3.2); — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.4.1 f; third-level clause with no CONTENIDO entry -> cited as the §5.2 span p.11–15) [VC] — planning-level restatement of flow_geographic_location on ws 03 (STAGED S-11)', verified_at=now() where id='0c03810a-0e36-4772-a3fb-1493c681c79e' and verification_status not in ('verified_against_standard','corrected');
-- seasonal_aspects
update public.fields set verification_status='verified_against_standard', verification_quote='Entre otros datos por recopilar, los siguientes datos relacionados con el agua se deben considerar para su recopilación: [...] g) aspectos estacionales en los flujos del agua; extracción y liberación, o cambios en la calidad del agua, cuando sea pertinente; — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.4.1 g; third-level clause with no CONTENIDO entry -> cited as the §5.2 span p.11–15) [VC] — "cuando sea pertinente" matches is_required=false', verified_at=now() where id='01528e32-dfef-426a-bab4-2ffdbeac5f9f' and verification_status not in ('verified_against_standard','corrected');
-- temporal_aspects
update public.fields set verification_status='verified_against_standard', verification_quote='Entre otros datos por recopilar, los siguientes datos relacionados con el agua se deben considerar para su recopilación: [...] h) aspectos temporales en el uso del agua, incluyendo si es pertinente los tiempos en el uso del agua y la duración del almacenamiento del agua. — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.4.1 h; third-level clause with no CONTENIDO entry -> cited as the §5.2 span p.11–15) [VC] — "si es pertinente" matches is_required=false', verified_at=now() where id='f28a33a6-3e3e-49e8-868e-d9b16e296f6c' and verification_status not in ('verified_against_standard','corrected');
-- data_quality_requirements
update public.fields set verification_status='verified_against_standard', verification_quote='Los requisitos para la calidad de los datos deberían tratar lo siguiente: a) cobertura relacionada con el tiempo: antigüedad de los datos y período de tiempo mínimo en el que se deberían recopilar los datos; b) cobertura geográfica: área geográfica donde se deberían recopilar los datos de los procesos unitarios para satisfacer el objetivo del estudio; c) cobertura tecnológica: tecnología específica o mezcla de tecnologías; d) precisión: medida de la variabilidad de los valores de los datos para cada dato expresado (por ejemplo: varianza); e) integridad: porcentaje de datos que se han medido o estimado; [...] j) incertidumbre de la información (por ejemplo: datos, modelos y suposiciones). — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.4.2 a–j; third-level clause with no CONTENIDO entry -> cited as the §5.2 span p.11–15) [VC] — CAVEAT: "deberían tratar" = SHOULD. The field is is_required=true and block gate REQ-06 enforces it (STAGED S-2, S-6). Items f) representatividad, g) coherencia, h) reproducibilidad, i) fuentes de los datos are inside the [...] run', verified_at=now() where id='d94b4f09-749c-491e-aacb-c09a4f44e6e9' and verification_status not in ('verified_against_standard','corrected');
-- primary_data_preference
update public.fields set verification_status='verified_against_standard', verification_quote='Los datos primarios se deberían recopilar cuando sea factible. Los datos secundarios solamente se deberían utilizar para las entradas cuando la recopilación de los datos primarios no sean posibles o factibles y pueden incluir: datos procedentes de bibliografía, datos calculados, estimados, predicciones del modelo u otros datos representativos. Las razones para utilizar datos secundarios para procesos significativos deben justificarse y documentarse. — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.4.2; third-level clause with no CONTENIDO entry -> cited as the §5.2 span p.11–15) [VC] — CAVEAT: the preference itself is "se deberían" (should); only the JUSTIFICATION of secondary data is "deben". There is no field capturing that justification, yet gate REQ-06 quotes exactly that sentence (STAGED S-8)', verified_at=now() where id='92dab3b4-cca4-41f6-afe3-cca907e58e64' and verification_status not in ('verified_against_standard','corrected');
-- missing_data_treatment
update public.fields set verification_status='verified_against_standard', verification_quote='Se debe documentar el tratamiento de los datos que faltan. Cuando se hagan suposiciones, éstas deben indicarse claramente como tales y debe describirse la base de las suposiciones. Se debería evaluar la importancia de los datos que faltan. — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.4.3; third-level clause with no CONTENIDO entry -> cited as the §5.2 span p.11–15) [VC] — shall-anchored, so is_required=true and the block gate REQ-07 are correctly enforced', verified_at=now() where id='d77e0e38-3735-4964-bdf1-214135606a91' and verification_status not in ('verified_against_standard','corrected');
-- no_offsetting
update public.fields set verification_status='verified_against_standard', verification_quote='Los resultados de la huella de agua no deben incluir compensaciones. | NOTA La compensación es un mecanismo para compensar la huella de agua de un producto, proceso u organización mediante actividades que reducen los impactos del agua en un proceso fuera de los límites del sistema del producto. — printed p.11–15', verification_note='md-verified 2026-09-05 (§5.2.5; third-level clause with no CONTENIDO entry -> cited as the §5.2 span p.11–15) [VC] — a printed PROHIBITION; the field is the attestation and block gate REQ-08 (no_offsetting == true) enforces it in the right polarity', verified_at=now() where id='10d470ce-12b6-48c3-953b-08ba4a4f9965' and verification_status not in ('verified_against_standard','corrected');

-- ######################## ISO-14046-03 · Analyse des Wasser-Fußabdruck-Inventars ########################
-- elementary_flow_quantity
update public.fields set verification_status='verified_against_standard', verification_quote='En general, la información de cada flujo elemental, donde sea pertinente debería incluir: a) cantidades de agua utilizada: masa, o volumen (por ejemplo entradas de agua y salidas de agua); | Flujo elemental de agua. Agua que entra al sistema bajo estudio, que ha sido extraída del medio ambiente; o agua que sale del sistema bajo estudio que es liberada al medio ambiente. — printed p.16–21, p.1', verification_note='md-verified 2026-09-05 (§5.3.2 a + definition §3.1.9; §5.3.2 cited as the §5.3 span p.16–21, §3.1 starts p.1 per CONTENIDO) [VC] — CAVEAT on the encoded unit: the standard prints "masa, o volumen", i.e. EITHER a mass or a volume; the field is hard-coded to m3 and offers no mass alternative (STAGED S-13). CAVEAT on required-ness: the whole §5.3.2 attribute list is "debería incluir" and "donde sea pertinente" (should), yet the field is is_required=true (STAGED S-2)', verified_at=now() where id='c0e5ce88-936a-4f43-a8ce-c3aa4bdb95eb' and verification_status not in ('verified_against_standard','corrected');
-- calculation_procedures_documented
update public.fields set verification_status='verified_against_standard', verification_quote='Los cálculos del inventario deben seguir los procedimientos descritos en la Norma ISO 14044 (véase también la Figura 2). a) El cálculo de los datos debe estar de acuerdo con el apartado 4.3.3 de la Norma ISO 14044:2006: todos los procedimientos de cálculo deben documentarse explícitamente y se deben especificar y explicar claramente las suposiciones realizadas. Se deberían aplicar los mismos procedimientos de cálculo regularmente a lo largo de todo el estudio. — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.1 a; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — the referenced ISO 14044:2006 §4.3.3 is NOT in the library (NR); only the ISO 14046 duty to follow it is verified here', verified_at=now() where id='ccebc649-6cfc-4600-9696-ef361454064f' and verification_status not in ('verified_against_standard','corrected');
-- data_validation_done
update public.fields set verification_status='verified_against_standard', verification_quote='b) La validación de los datos debe realizarse de acuerdo con el apartado 4.3.3.2 de la Norma ISO 14044:2006: una verificación de la validez de los datos debe realizarse durante el proceso de recopilación de datos para confirmar y proporcionar evidencia de que se han cumplido los requisitos de la calidad de los datos para la aplicación prevista. La validación puede implicar, por ejemplo: realizar balances de materia de agua y/o análisis comparativo de factores de liberación en agua. — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.1 b; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — ISO 14044:2006 §4.3.3.2 is NR', verified_at=now() where id='9c3c451f-3cdb-41fb-9780-01f46913851d' and verification_status not in ('verified_against_standard','corrected');
-- sensitivity_analysis_boundary
update public.fields set verification_status='verified_against_standard', verification_quote='e) El ajuste de los límites del sistema debe hacerse de acuerdo con el apartado 4.3.3.4 de la Norma ISO 14044:2006. Reflejar la naturaleza iterativa de la evaluación de la huella de agua, las decisiones respecto a los datos que se van a incluir deben basarse en un análisis de sensibilidad para determinar su importancia, por lo tanto verificar el análisis inicial descrito en 5.2. Los límites iniciales del sistema se deben revisar, según corresponda, de acuerdo con los criterios de corte establecidos en la definición del alcance. Se deben documentar los resultados de este proceso de ajuste y del análisis de sensibilidad. — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.1 e; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — shall-anchored, so is_required=true is correct. No gate reads this field (STAGED S-10)', verified_at=now() where id='d6434952-bdb1-4e21-943c-14a96b19e4f4' and verification_status not in ('verified_against_standard','corrected');
-- inventory_balance_explained
update public.fields set verification_status='verified_against_standard', verification_quote='El inventario de la huella de agua debe incluir entradas y salidas para cada proceso unitario que forme parte del sistema en estudio. Cualquier discrepancia en el balance del inventario debe explicarse. — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.2; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — this is the ONE shall in §5.3.2; the a)–g) attribute list that follows it is "debería"', verified_at=now() where id='9986413e-2a5b-4afe-9d0d-79ea7004f275' and verification_status not in ('verified_against_standard','corrected');
-- flow_water_resource_type
update public.fields set verification_status='verified_against_standard', verification_quote='En general, la información de cada flujo elemental, donde sea pertinente debería incluir: [...] b) recursos tipo de agua utilizada: - pluvial; - agua superficial; - agua de mar; - agua salobre; - agua subterránea (excluyendo agua fósil); - aguafósil; — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.2 b; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — the six enum tokens are exactly the six printed resource types, in printed order; "aguafósil" is the transcript as printed. Unlike the d) list this one is NOT introduced by "por ejemplo", so it reads as closed. CAVEAT: the whole list sits under "debería incluir" while the field is is_required=true and block gate REQ-10 enforces it (STAGED S-2, S-6)', verified_at=now() where id='c2509f77-5e58-4519-803c-24159ff863f2' and verification_status not in ('verified_against_standard','corrected');
-- flow_quality_parameters
update public.fields set verification_status='verified_against_standard', verification_quote='En general, la información de cada flujo elemental, donde sea pertinente debería incluir: [...] c) parámetros y/o características de calidad del agua por ejemplo: características físicas (por ejemplo termal), químicas y biológicas o descriptores funcionales de la calidad del agua; — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.2 c; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — open list ("por ejemplo"), so data_type=text is right. Same should-vs-block caveat as flow_water_resource_type', verified_at=now() where id='8d248258-fc9f-4937-9c55-3fba11106544' and verification_status not in ('verified_against_standard','corrected');
-- flow_form_of_use
update public.fields set verification_status='verified_against_standard', verification_quote='En general, la información de cada flujo elemental, donde sea pertinente debería incluir: [...] d) formas de uso del agua, por ejemplo: - evaporación; - transpiración; - integración en el producto; - liberación en diferentes cuencas hidrográficas o en el mar; - desplazamiento de agua de un tipo de recurso fuente de agua a otro tipo de recurso de agua dentro de una cuenca hidrográfica por ejemplo: agua subterránea hacia agua superficial; - otras formas de uso del agua; por ejemplo: uso en lascorrientes; — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.2 d; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — the list is EXEMPLARY ("por ejemplo"), and the encoded enum correctly carries an "other" token plus an "instream_use" token for "uso en lascorrientes" (transcript as printed). Same should-vs-block caveat as flow_water_resource_type', verified_at=now() where id='ff05f4d5-0ba0-485a-be0f-a00b5cc62eaf' and verification_status not in ('verified_against_standard','corrected');
-- flow_geographic_location
update public.fields set verification_status='verified_against_standard', verification_quote='En general, la información de cada flujo elemental, donde sea pertinente debería incluir: [...] e) ubicación geográfica del uso del agua o de su afectación (incluyendo extracción y/o liberación del agua): información de la ubicación física del uso del agua o de su afectación incluyendo la extracción y liberación (como sitio específico, según sea necesario) o bien la asignación de las ubicaciones físicas hacia una categoría derivada de una clasificación apropiada de las cuencas hidrográficas o de las regiones; — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.2 e; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — NOTA 1 to the same item adds that some environmental-condition indicators need the location of use. Same should-vs-block caveat', verified_at=now() where id='c5b20bd3-81d2-4294-83f1-26b6ff279b07' and verification_status not in ('verified_against_standard','corrected');
-- flow_temporal_aspects
update public.fields set verification_status='verified_against_standard', verification_quote='En general, la información de cada flujo elemental, donde sea pertinente debería incluir: [...] f) aspectos temporales del uso del agua, por ejemplo tiempo de uso y liberación si el período de residencia pertinente ocurre dentro de los límites del sistema; — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.2 f; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — conditional and exemplary, matching is_required=false', verified_at=now() where id='3dbfc9d0-45a7-4e68-b221-bca84a434b33' and verification_status not in ('verified_against_standard','corrected');
-- flow_releases_to_environment
update public.fields set verification_status='verified_against_standard', verification_quote='En general, la información de cada flujo elemental, donde sea pertinente debería incluir: [...] g) emisiones al aire o vertidos al agua y al suelo que impactan en la calidad del agua. | NOTA 2 Puede haber otras emisiones al aire y vertidos al suelo en el sistema bajo estudio, que no impacten a la calidad del agua, los cuales no se incluyen; por ejemplo: emisiones directas al aire que contribuyan a dañar la salud humana solamente por inhalación. — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.2 g + NOTA 2; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — matches §1 "Sólo las emisiones al aire y los vertidos al suelo con impactos en la calidad del agua se incluyen en la evaluación" (p.1)', verified_at=now() where id='864087c2-0499-4850-a8cc-c6019bb72516' and verification_status not in ('verified_against_standard','corrected');
-- allocation_balance_preserved
update public.fields set verification_status='verified_against_standard', verification_quote='La suma de las entradas y salidas asignadas de un proceso unitario deben ser iguales a las entradas y salidas del proceso unitario antes de la asignación. — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.3.1; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — a printed mass-balance identity encoded as a boolean attestation rather than a checked equation; no engine check exists (STAGED S-14)', verified_at=now() where id='ae5fa1d0-8acd-4711-a05a-1a33f436effa' and verification_status not in ('verified_against_standard','corrected');
-- allocation_sensitivity_done
update public.fields set verification_status='verified_against_standard', verification_quote='Cada vez que diversos procedimientos de asignación alternativos parezcan posibles de aplicar, se debe efectuar un análisis de sensibilidad para ilustrar las consecuencias de la desviación del enfoque seleccionado. — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.3.1; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — a CONDITIONAL shall (only where alternative allocation procedures look applicable), which is why is_required=false is defensible; block gate REQ-11 nevertheless demands it unconditionally (STAGED S-4)', verified_at=now() where id='127f3def-d07e-4529-8c5a-faf654f35bab' and verification_status not in ('verified_against_standard','corrected');
-- recycling_allocation_type
update public.fields set verification_status='verified_against_standard', verification_quote='a) Un procedimiento de asignación de "ciclo cerrado" se aplica a sistemas de producto de "ciclo cerrado". También se aplica en sistemas de producto de "ciclo abierto" en que no ocurren cambios en las propiedades inherentes del material reciclado. En estos casos se evita la necesidad de asignación ya que la utilización de material secundario sustituye a la utilización de material virgen (primario). [...] b) Un procedimiento de asignación de "ciclo abierto" se aplica en sistemas producto de "ciclo abierto" en los que el material se recicla en otros sistemas de producto y el material sufre un cambio en sus propiedades inherentes. — printed p.16–21', verification_note='md-verified 2026-09-05 (§5.3.3.3; third-level clause with no CONTENIDO entry -> cited as the §5.3 span p.16–21) [VC] — the two enum tokens are exactly the two printed procedures; applicable only in reuse/recycling situations, matching is_required=false', verified_at=now() where id='bdff0fef-8172-494b-a7ad-47292b658df6' and verification_status not in ('verified_against_standard','corrected');

-- ######################## ISO-14046-04 · Wirkungsabschätzung des Wasser-Fußabdrucks ########################
-- impact_categories
update public.fields set verification_status='verified_against_standard', verification_quote='Los impactos relacionados con el agua están asociados con numerosos mecanismos ambientales y por lo tanto numerosos indicadores de categoría son posibles. El indicador de categoría o los indicadores de categoría, y el método o métodos de evaluación del impacto de la huella de agua se deben seleccionar con base en los objetivos y el alcance del estudio. | Categoría de impacto. Clase que representa asuntos ambientales de interés a la cual se pueden asignar los resultados del análisis del inventario del ciclo de vida (3.3.6). — printed p.22–26, p.3', verification_note='md-verified 2026-09-05 (§5.4.2 + definition §3.3.11; §5.4.2 cited as the §5.4 span p.22–26, §3.3 starts p.3 per CONTENIDO) [VC]', verified_at=now() where id='9d3eb64d-f29d-496f-b4db-a43edf83c172' and verification_status not in ('verified_against_standard','corrected');
-- category_indicators
update public.fields set verification_status='verified_against_standard', verification_quote='El indicador de categoría o los indicadores de categoría, se pueden elegir en cualquier parte a lo largo del mecanismo ambiental del modelo o de los modelos de caracterización. El nombre del indicador de categoría de impacto debe ser lo suficientemente explícito como para expresar con claridad a qué mecanismo ambiental se refiere. Cada indicador de categoría de impacto debe documentarse de manera que refleje a qué mecanismo ambiental se refiere. — printed p.22–26', verification_note='md-verified 2026-09-05 (§5.4.2; third-level clause with no CONTENIDO entry -> cited as the §5.4 span p.22–26) [VC]', verified_at=now() where id='cd312bae-5668-4e35-9d11-1056aa04adb3' and verification_status not in ('verified_against_standard','corrected');
-- characterization_model
update public.fields set verification_status='verified_against_standard', verification_quote='El método para calcular los resultados del indicador debe identificarse y documentarse incluyendo los juicios de valor y las suposiciones utilizadas. | El método o métodos de evaluación del impacto de la huella de agua deben considerar el impacto o los impactos ambientales potenciales debidos al cambio en la cantidad del agua y/o al cambio en la calidad de las aguas causados por el sistema bajo estudio. | La elección de los métodos de caracterización y los factores para cada categoría de impacto evaluada se deben explicar y justificar. — printed p.22–26', verification_note='md-verified 2026-09-05 (§5.4.4.1; third-level clause with no CONTENIDO entry -> cited as the §5.4 span p.22–26) [VC]', verified_at=now() where id='fdf0e6b1-b185-4dcb-9154-ab88ba9ef4af' and verification_status not in ('verified_against_standard','corrected');
-- characterization_factor
update public.fields set verification_status='verified_against_standard', verification_quote='Factor de caracterización. Factor que surge de un modelo de caracterización que se aplica para convertir el resultado del análisis del inventario del ciclo de vida (3.3.6) asignado a la unidad común del indicador de categoría (3.3.12). NOTA 1 a la entrada La unidad común permite reagrupar los resultados en un mismo indicador de categoría. | El cálculo de las huellas del agua por escasez debería realizarse utilizando factores de caracterización derivados de los modelos de caracterización que se contabilizan por las diferencias locales en la escasez de agua. — printed p.3, p.22–26', verification_note='md-verified 2026-09-05 (definition §3.3.14, FUENTE ISO 14044:2006 3.37, + §5.4.5; §3.3 starts p.3 per CONTENIDO, §5.4.5 cited as the §5.4 span p.22–26) [VC] — CAVEAT: the md prints NO numeric characterization factors and NO table of them; ISO 14046 leaves the values to the chosen characterization model, so the encoded unit "-" is a placeholder and every project value is engineer_input/derived, never standard_fixed', verified_at=now() where id='9efd94c6-6b6c-430f-a077-5a216f92b0bb' and verification_status not in ('verified_against_standard','corrected');
-- lci_result
update public.fields set verification_status='verified_against_standard', verification_quote='Si el cálculo de la huella de agua se basa en categorías de impacto diferentes, los resultados del inventario del ciclo de vida deben asignarse a éstas categorías de impacto diferentes. | Análisis del inventario del ciclo de vida. ICV. Fase del análisis del ciclo de vida (3.3.4) que implica la recopilación y la cuantificación de entradas y resultados de un sistema del producto durante su ciclo de vida. — printed p.22–26, p.3', verification_note='md-verified 2026-09-05 (§5.4.3 "Clasificación" + definition §3.3.6; §5.4.3 cited as the §5.4 span p.22–26, §3.3 starts p.3 per CONTENIDO) [VC] — the md heading lost its prefix and reads "3. Clasificación"; the clause number is reconstructed from the §5.4 sub-clause sequence', verified_at=now() where id='c04230d6-02b1-46cc-bd7a-1483828fab14' and verification_status not in ('verified_against_standard','corrected');
-- category_indicator_result
update public.fields set verification_status='verified_against_standard', verification_quote='Indicador de categoría de impacto. Representación cuantificable de una categoría de impacto (3.3.11). | Factor de caracterización. Factor que surge de un modelo de caracterización que se aplica para convertir el resultado del análisis del inventario del ciclo de vida (3.3.6) asignado a la unidad común del indicador de categoría (3.3.12). NOTA 1 a la entrada La unidad común permite reagrupar los resultados en un mismo indicador de categoría. | Los impactos relacionados con el agua se pueden representar por uno o más parámetros que cuantifiquen los impactos ambientales potenciales de un sistema del producto, proceso u organización relacionados con el agua, incluyendo: - el resultado del indicador de la huella de agua (por ejemplo: huella de agua por escasez), relacionado con una sola categoría de impacto — printed p.3, p.22–26', verification_note='md-verified 2026-09-05 (definitions §3.3.12 / §3.3.14 + §5.4.1; §3.3 starts p.3 per CONTENIDO, §5.4.1 cited as the §5.4 span p.22–26) [VC] — CAVEAT: this is the OUTPUT of EQ-01, and the md prints NO formula anywhere. The sum-of-products form is DERIVED from the definitions quoted here plus §5.4.1 "La evaluación del impacto de la huella de agua debe cumplir con la Norma ISO 14044."; ISO 14044 is not in the library (NR), so the arithmetic itself stays unverified (see Section B)', verified_at=now() where id='97e30065-1449-482a-a5d5-324b4bd9d79e' and verification_status not in ('verified_against_standard','corrected');
-- water_footprint_profile
update public.fields set verification_status='verified_against_standard', verification_quote='Un perfil de la huella de agua considera un rango de impactos ambientales potenciales asociados con el agua. Un perfil de la huella de agua está hecho con varios resultados de indicadores de categorías de impacto, que se calculan a partir de varias categorías de impacto. | Si un perfil de la huella de agua no es integral, se debería informar de manera transparente utilizando un calificativo. | Los impactos ambientales potenciales cubiertos por el perfil de la huella de agua se deben describir y las consecuencias previsibles de los impactos ambientales potenciales excluidos relacionados con el agua deben identificarse. — printed p.22–26', verification_note='md-verified 2026-09-05 (§5.4.7 + definition §3.3.13 p.3; §5.4.7 cited as the §5.4 span p.22–26) [VC] — the third sentence is the duty gate REQ-15 quotes, yet REQ-15 does NOT read this field (STAGED S-8)', verified_at=now() where id='e7163937-aa16-4077-9ac3-95e606ed9abf' and verification_status not in ('verified_against_standard','corrected');
-- weighting_applied
update public.fields set verification_status='verified_against_standard', verification_quote='El perfil de la huella de agua se puede agregar como un solo parámetro. Si se aplica la ponderación, esta se debe de realizar e informar de acuerdo con la Norma ISO 14044. | Si se aplica la ponderación, los resultados no deben utilizarse como base de una aseveración comparativa prevista para su divulgación al público. — printed p.22–26', verification_note='md-verified 2026-09-05 (§5.4.7, echoed in §5.4.1 and §5.1; cited as the §5.4 span p.22–26) [VC] — the second sentence is a printed PROHIBITION combining weighting_applied with comparative_assertion_public; NO gate enforces it today (REQ-15 only checks both fields are non-null) — STAGED S-8', verified_at=now() where id='beefe1e6-f9b0-4489-aa21-4aea1a7b2bf4' and verification_status not in ('verified_against_standard','corrected');
-- geo_temporal_considered
update public.fields set verification_status='verified_against_standard', verification_quote='Las cuestiones sobre el agua son de carácter local y están relacionadas con una cuenca hidrográfica y con características específicas de precipitación, hidrológicas, geográficas; y a las condiciones climáticas, eco-sistémicas y socio-económicas. La evaluación del impacto de la huella de agua debe considerar las condiciones locales y puede, cuando aplique, estar relacionada con cuestiones más amplias regionales y globales. | Los aspectos de temporalidad, incluyendo el estacional, se deben considerar también cuando sea pertinente. — printed p.22–26', verification_note='md-verified 2026-09-05 (§5.4.4.2; third-level clause with no CONTENIDO entry -> cited as the §5.4 span p.22–26) [VC] — shall-anchored, so is_required=true and block gate REQ-14 are correctly enforced', verified_at=now() where id='488dbdb7-2ba6-4085-878c-617f1dff141d' and verification_status not in ('verified_against_standard','corrected');

-- ######################## ISO-14046-05 · Auswertung der Ergebnisse ########################
-- significant_issues
update public.fields set verification_status='verified_against_standard', verification_quote='La fase de interpretación de la huella de agua debe incluir lo siguiente: a) identificación de las cuestiones significativas basadas en los resultados de la evaluación de la huella de agua por ejemplo: procesos con una contribución significativa al cálculo de las huellas del agua, mecanismos ambientales principalmente afectados, flujos elementales que tienen la mayor contribución a los resultados de la evaluación de la huella de agua; — printed p.27', verification_note='md-verified 2026-09-05 (§5.5 a, printed p.27 per CONTENIDO) [VC]', verified_at=now() where id='4949d890-9e76-49df-b802-95a0ebb9cc04' and verification_status not in ('verified_against_standard','corrected');
-- completeness_check
update public.fields set verification_status='verified_against_standard', verification_quote='La fase de interpretación de la huella de agua debe incluir lo siguiente: [...] b) evaluación que considera las verificaciones de los análisis de integridad, sensibilidad y coherencia; — printed p.27', verification_note='md-verified 2026-09-05 (§5.5 b, printed p.27 per CONTENIDO) [VC] — CAVEAT: the standard prints ONE item b) naming three checks (integridad / sensibilidad / coherencia); the encoding splits it into completeness_check + sensitivity_check + consistency_check. The split is the encoders, not the standards (STAGED S-11)', verified_at=now() where id='c3fe05e1-7937-48b3-a19f-10b848e75792' and verification_status not in ('verified_against_standard','corrected');
-- sensitivity_check
update public.fields set verification_status='verified_against_standard', verification_quote='La fase de interpretación de la huella de agua debe incluir lo siguiente: [...] b) evaluación que considera las verificaciones de los análisis de integridad, sensibilidad y coherencia; [...] g) consideraciones del análisis de sensibilidad para proporcionar rangos acerca de los resultados informados. NOTA El apartado B.3.3 de la Norma ISO 14044:2006 proporciona orientación adicional para realizar la verificación del análisis de sensibilidad. — printed p.27', verification_note='md-verified 2026-09-05 (§5.5 b + g + NOTA, printed p.27 per CONTENIDO) [VC] — same one-item-split-into-three caveat as completeness_check; ISO 14044:2006 §B.3.3 is NR', verified_at=now() where id='e2618ba7-303e-4ac8-bb0a-c54c718229d6' and verification_status not in ('verified_against_standard','corrected');
-- consistency_check
update public.fields set verification_status='verified_against_standard', verification_quote='La fase de interpretación de la huella de agua debe incluir lo siguiente: [...] b) evaluación que considera las verificaciones de los análisis de integridad, sensibilidad y coherencia; | Cuando se comparan las huellas del agua de diferentes sistemas del producto, procesos u organizaciones, se debería realizar una verificación del análisis de coherencia, tal como se describe en la Norma ISO 14044. — printed p.27, p.28', verification_note='md-verified 2026-09-05 (§5.5 b + §6.1; §5.5 p.27 and §6.1 p.28 per CONTENIDO) [VC] — same one-item-split-into-three caveat as completeness_check', verified_at=now() where id='d83090ef-6450-4ab8-8f70-1fbc28454ee4' and verification_status not in ('verified_against_standard','corrected');
-- conclusions
update public.fields set verification_status='verified_against_standard', verification_quote='La fase de interpretación de la huella de agua debe incluir lo siguiente: [...] d) conclusiones de la evaluación de la huella de agua; — printed p.27', verification_note='md-verified 2026-09-05 (§5.5 d, printed p.27 per CONTENIDO) [VC]', verified_at=now() where id='3b86deee-ee9b-488b-85c7-b53ef2328fa3' and verification_status not in ('verified_against_standard','corrected');
-- limitations
update public.fields set verification_status='verified_against_standard', verification_quote='La fase de interpretación de la huella de agua debe incluir lo siguiente: [...] e) limitaciones de la evaluación de la huella de agua; | Una evaluación de la huella de agua de una situación particular no es suficiente para utilizarse en la descripción completa de los impactos ambientales potenciales de productos, procesos u organizaciones (véase introducción). — printed p.27', verification_note='md-verified 2026-09-05 (§5.5 e + §5.6; both printed p.27 per CONTENIDO) [VC]', verified_at=now() where id='59a49975-19d0-4722-a166-2bf0552b9b3e' and verification_status not in ('verified_against_standard','corrected');
-- uncertainty_assessment
update public.fields set verification_status='verified_against_standard', verification_quote='La fase de interpretación de la huella de agua debe incluir lo siguiente: [...] f) evaluación cualitativa y/o cuantitativa de la incertidumbre, por ejemplo mediante la aplicación del método de simulación de Monte Carlo; | Análisis de la incertidumbre. Procedimiento sistemático para cuantificar la incertidumbre introducida en los resultados de un análisis de inventario del ciclo de vida (3.3.6) debido a los efectos acumulativos de la imprecisión del modelo, de la incertidumbre de las entradas y de la variabilidad de los datos. — printed p.27, p.7', verification_note='md-verified 2026-09-05 (§5.5 f + definition §3.6.3; §5.5 p.27 and §3.6 p.7 per CONTENIDO) [VC] — inside the same shall-list as the other §5.5 items, yet block gate REQ-16 omits this field while enforcing a)–e) (STAGED S-10)', verified_at=now() where id='dd4bb34f-9876-4113-b256-4b59a77f9ed2' and verification_status not in ('verified_against_standard','corrected');

-- ######################## ISO-14046-06 · Berichterstattung ########################
-- report_prepared
update public.fields set verification_status='verified_against_standard', verification_quote='Los resultados y conclusiones de la evaluación de la huella de agua deben informarse de forma completa, exacta y sin sesgo al público previsto. Los resultados, datos, métodos, suposiciones y limitaciones deben ser transparentes y presentarse con suficiente detalle para permitir al lector comprender las complejidades de las compensaciones de información inherentes a la evaluación de la huella de agua. El informe también debe permitir que los resultados e interpretación se utilicen de forma coherente con los objetivos del estudio. — printed p.28', verification_note='md-verified 2026-09-05 (§6.1, printed p.28 per CONTENIDO) [VC] — note the opening sentence of §6.1 is only "debería" ("El informe [...] debería seguir las reglas especificadas en la Norma ISO 14044"); the shall quoted here is the one the field rests on', verified_at=now() where id='a6bdeba5-04b6-42e6-b3ad-7028745c3ea8' and verification_status not in ('verified_against_standard','corrected');
-- water_types_impacts_explicit
update public.fields set verification_status='verified_against_standard', verification_quote='Los tipos del recurso de agua utilizados y los impactos ambientales potenciales relacionados con el agua tratados por el método o los métodos de evaluación del impacto de la huella de agua utilizados deben ser explícitos. — printed p.28', verification_note='md-verified 2026-09-05 (§6.1, printed p.28 per CONTENIDO) [VC]', verified_at=now() where id='3a3d3bff-0c05-4451-aadd-dbd4fe959282' and verification_status not in ('verified_against_standard','corrected');
-- third_party_report
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando se realiza el informe de los resultados de la evaluación de la huella de agua a una tercera parte (es decir, otras partes interesadas distintas de quien encarga o realiza el estudio), se debe preparar un informe de tercera parte. | El informe de tercera parte constituye un documento de referencia y debe estar disponible para cualquier tercera parte a la cual se informa sobre la evaluación de la huella de agua y los resultados de la huella de agua. El informe de tercera parte debe cubrir los siguientes aspectos: a) aspectos generales [...] g) revisión crítica, cuando aplique — printed p.29', verification_note='md-verified 2026-09-05 (§6.2, printed p.29 per CONTENIDO) [VC] — CAVEAT: §6.2 prints a mandatory a)–g) content list roughly 60 items deep (md lines 910–984); the encoding compresses all of it into one boolean attestation, so nothing in the app checks the individual required report contents (STAGED S-14)', verified_at=now() where id='0d73ddee-20a8-42f9-b255-d9a1b2cb8d3c' and verification_status not in ('verified_against_standard','corrected');
-- comparative_study_equivalence
update public.fields set verification_status='verified_against_standard', verification_quote='En un estudio comparativo, la equivalencia de los sistemas que van a compararse debe evaluarse antes de la interpretación de los resultados. En consecuencia, el alcance del estudio se debe definir de tal manera que los sistemas puedan comparase. Los sistemas deben compararse utilizando la misma unidad funcional y consideraciones metodológicas equivalentes, tales como desempeño, alcance geográfico, límites del sistema, calidad de los datos, procedimientos de asignación, reglas de decisión al evaluar entradas y salidas y reglas de decisión sobre la evaluación del impacto. Cualquier diferencia entre los sistemas con respecto a estos parámetros se debe identificar y se debe realizar el informe. — printed p.32', verification_note='md-verified 2026-09-05 (§6.3.2; third-level clause with no CONTENIDO entry -> cited as the §6.3 page p.32) [VC] — "puedan comparase" is the transcript as printed. Conditional on a comparative study, matching is_required=false', verified_at=now() where id='df94ce75-ea63-4428-a271-3188a719dcc8' and verification_status not in ('verified_against_standard','corrected');

-- ######################## ISO-14046-07 · Kritische Prüfung ########################
-- critical_review_performed
update public.fields set verification_status='verified_against_standard', verification_quote='Una evaluación de la huella de agua que es parte de un estudio del análisis del ciclo de vida prevista para una aseveración comparativa para su divulgación al público, debe aplicar los requisitos pertinentes de la Norma ISO 14044 y estar sujeta notablemente a una revisión crítica. En ese caso, se deben aplicar los mismos procedimientos y requisitos de la Norma ISO 14044. [...] Para los estudios no previstos para utilizarse en aseveraciones comparativas, aunque la revisión crítica no se requiere, dicha revisión crítica también es posible y esta información puede ser de ayuda, según sea apropiado. — printed p.33', verification_note='md-verified 2026-09-05 (§7.1, printed p.33 per CONTENIDO) [VC] — a CONDITIONAL shall, correctly encoded as is_required=false and correctly enforced by REQ-20 as an implication (comparative_assertion_public == false OR critical_review_performed == true)', verified_at=now() where id='40e9aeb2-8982-4750-9c7d-1435044a9742' and verification_status not in ('verified_against_standard','corrected');
-- critical_review_statement
update public.fields set verification_status='verified_against_standard', verification_quote='Una revisión crítica la puede realizar un experto interno o externo. En este caso un experto independiente de la evaluación de la huella de agua debe realizar la revisión. La declaración de revisión, los comentarios de quien realiza el estudio y cualquier respuesta a las recomendaciones realizadas por el revisor deben incluirse en el informe de la evaluación de la huella de agua. | La declaración de revisión y el informe del panel de revisión, así como los comentarios del experto y cualquier respuesta a las recomendaciones hechas por el revisor o el panel deben incluirse en el informe de la evaluación de la huella de agua. — printed p.34', verification_note='md-verified 2026-09-05 (§7.3 + §7.4, both printed p.34 per CONTENIDO; the md headings lost their prefixes and read "3. REVISIÓN CRÍTICA POR UN EXPERTO INTERNO O EXTERNO" and "4. REVISIÓN CRÍTICA POR UN PANEL DE PARTES INTERESADAS") [VC]', verified_at=now() where id='fe7947ae-7087-45cb-8f1f-9b954a24ed1d' and verification_status not in ('verified_against_standard','corrected');
-- review_panel_members
update public.fields set verification_status='verified_against_standard', verification_quote='Una revisión crítica se puede realizar como una revisión por las partes interesadas. En este caso, quien encarga el estudio original debería seleccionar un experto externo independiente para presidir un panel de revisión constituido por al menos tres miembros. Con base en el objetivo y el alcance del estudio, el presidente debería seleccionar otros revisores independientes calificados. — printed p.34', verification_note='md-verified 2026-09-05 (§7.4, printed p.34 per CONTENIDO) [VC] — the only printed NUMERIC threshold in the whole standard: "al menos tres miembros" (at least three). It is stated under "debería" (should), and NO gate enforces a minimum on this field today (STAGED S-9 proposes a warn gate, never a block)', verified_at=now() where id='e3f0f872-272a-49dd-95e4-df4a546f8ca8' and verification_status not in ('verified_against_standard','corrected');


-- ######################## SECTION B · EQUATIONS (quote backfill only — status untouched) ########################
-- EQ-01 category_indicator_result = SUM(lci_result * characterization_factor) — ws ISO-14046-04, clause §5.4.4.1,
--   current verification_status = 'verified_via_cross_reference' (encode-time source_quote present, verification_quote null).
--   The md prints NO formula and NO worked example for this anywhere; ISO 14046 hands all characterization arithmetic to
--   ISO 14044 (§5.4.1) and ISO 14044 is not in the library (NR). Under SR-1 a definition is not a formula, so the STATUS IS
--   NOT LIFTED here — only the printed definitions the encoded form rests on are recorded as the verification_quote.
update public.equations set verification_quote='La evaluación del impacto de la huella de agua debe cumplir con la Norma ISO 14044. NOTA Véase el apartado 4.4 de la Norma ISO 14044:2006. | Factor de caracterización. Factor que surge de un modelo de caracterización que se aplica para convertir el resultado del análisis del inventario del ciclo de vida (3.3.6) asignado a la unidad común del indicador de categoría (3.3.12). NOTA 1 a la entrada La unidad común permite reagrupar los resultados en un mismo indicador de categoría. | Si el cálculo de la huella de agua se basa en categorías de impacto diferentes, los resultados del inventario del ciclo de vida deben asignarse a éstas categorías de impacto diferentes. — printed p.22–26, p.3', verification_note=coalesce(verification_note,'') || ' | md-quote 2026-09-05 (§5.4.1 + §3.3.14 + §5.4.3, printed p.22–26 / p.3) [VC] — RESIDUE for a status lift: the md prints NO formula and NO worked example for EQ-01; the sum-of-products form is DERIVED from the definition of the characterization factor plus the §5.4.3 classification duty, and the arithmetic itself lives in ISO 14044 (not in the library, NR). Status deliberately left at verified_via_cross_reference.' where id='db1f6227-b23a-4d7e-b0c1-56a80b1977da' and verification_quote is null;
